head.script:
// 데이터/옵션 분리: JSON 은 순수 데이터만, 아래 type+옵션은 스크립트가 보유 → 렌더시 조합
scwin.CHART_TYPE = "imageSingle";                    // 차트 타입 (스크립트)
scwin.CHART_DATA_URL ="/ui/sample/SBChart/IMAGESINGLE/data/IMAGESINGLE.json";             // 순수 데이터 JSON (type 없음)
scwin.CHART_CONFIG = {
  "axis": {   // 축 설정
    "x": {
      "type": "category",   // 타입
      "categories": [   // 범주 목록
        "매체를 통한 영화감상"
      ]
    }
  },
  "extend": {   // 차트별 세부 옵션
    "imageSingle": {   // 이미지단일 전용 옵션
      "padding": 25   // 안쪽 여백
    }
  },
  "dataOpts": {   // 데이터 레벨 옵션(keys/labels 등)
    "imageConf": [   // 이미지 매핑 설정
      {
        "key": "device1",   // 키 필드
        "src":"/ui/sample/SBChart/images/device-1.png",   // 이미지 경로
        "repeat": false,   // 반복 여부
        "rectColor": "#78B5E2"   // 배경 사각형 색
      },
      {
        "key": "device2",   // 키 필드
        "src":"/ui/sample/SBChart/images/device-2.png",   // 이미지 경로
        "repeat": false,   // 반복 여부
        "rectColor": "#5CC6CB"   // 배경 사각형 색
      },
      {
        "key": "device3",   // 키 필드
        "src":"/ui/sample/SBChart/images/device-3.png",   // 이미지 경로
        "repeat": false,   // 반복 여부
        "rectColor": "#7FC9A2"   // 배경 사각형 색
      },
      {
        "key": "device4",   // 키 필드
        "src":"/ui/sample/SBChart/images/device-4.png",   // 이미지 경로
        "repeat": false,   // 반복 여부
        "rectColor": "#A9C138"   // 배경 사각형 색
      }
    ],
    "legends": {   // 범례 항목들
      "device1": "TV/Radio",
      "device2": "PC/노트북",
      "device3": "스마트 기기",
      "device4": "Video/DVD"
    }
  }
};               // 옵션(global/axis/extend…) + dataOpts(keys/labels…)

scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData(scwin.CHART_TYPE, data, chartWrap, scwin.CHART_CONFIG);
};
